use std::collections::HashMap;impl Solution{pub fn is_scramble(a:String,b:String)->bool{fn f(a:&[u8],b:&[u8],i:usize,j:usize,n:usize,m:&mut HashMap<(usize,usize,usize),bool>)->bool{if let Some(&v)=m.get(&(i,j,n)){return v}let mut c=[0i32;26];for k in 0..n{c[(a[i+k]-b'a')as usize]+=1;c[(b[j+k]-b'a')as usize]-=1;}if c.iter().any(|&x|x!=0){m.insert((i,j,n),false);return false}if a[i..i+n]==b[j..j+n]{m.insert((i,j,n),true);return true}for k in 1..n{if f(a,b,i,j,k,m)&&f(a,b,i+k,j+k,n-k,m)||f(a,b,i,j+n-k,k,m)&&f(a,b,i+k,j,n-k,m){m.insert((i,j,n),true);return true}}m.insert((i,j,n),false);false}if a.len()!=b.len(){return false}f(a.as_bytes(),b.as_bytes(),0,0,a.len(),&mut HashMap::new())}}
